        emon.Testport.AssertThat(r >= 300, "three documents were run");
    }
    [Xunit.Fact]
    public static void TestTheThreeFixturesAndTheRealFilesAreTheSameThroughAnAsyncSourceOf512ByteChunks() {
        int r1 = CtAsyncRows(0, emon.Testport.TestFile("content/evidence.txt"), 1, 512);
        int r2 = CtAsyncRows(0, emon.Testport.TestFile("content/real.txt"), 1, 512);
