    internal static int CtCountPage(emon.Port.Cells gl, int page) {
        int n = Evidence.GlCount(gl);
        int g = 0;
        int c = 0;
        while (g < n) {
            if (Evidence.GlGet(gl, g, Evidence.GfPage()) == page) {
                c += 1;
            }
            g += 1;
        }
        return c;
    }
    internal static int CtRealRows(int emonT, byte[] rows) {
        // real.txt: `path page digest glyphs`. The file is one of corpus/ (not committed):
        // the digest of the page's glyph stream and its glyph count are what emon made of it
        // when pdfminer.six agreed, and must not change.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells sp = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        int n = emon.Port.BlobLen(rows);
        int pos = 0;
        int line = 0;
        int e = 0;
        int t1 = 0;
        int t2 = 0;
        int t3 = 0;
        int page = 0;
        int rowsn = 0;
        while (pos < n) {
            line += 1;
            e = CtNl(rows, pos);
            if ((pos < e) && (emon.Port.BlobU8(rows, pos) != 35)) {
                t1 = CtTab(rows, pos, e);
                t2 = CtTab(rows, t1 + 1, e);
                t3 = CtTab(rows, t2 + 1, e);
                page = CtDec(rows, t1 + 1, t2);
                rowsn += 1;
                emon.Testport.AssertEqAt(CtRun(emon.Port.SrcOfBlob(emon.Testport.TestFileSpan(rows, pos, t1)), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, pg, wd, ln), 0, "the file ran", line);
                emon.Testport.AssertEqAt(Contentrows.CrDigest(gl, et, page), CtDec(rows, t2 + 1, t3), "digest of the page's text", line);
                emon.Testport.AssertEqAt(CtCountPage(gl, page), CtDec(rows, t3 + 1, e), "glyphs on the page", line);
            }
            pos = e + 1;
        }
        return rowsn;
    }
    [Xunit.Fact]
    public static void TestRealFilesMakeTheGlyphStreamsPdfminerAgreedWith() {
        emon.Testport.AssertThat(CtRealRows(0, emon.Testport.TestFile("content/real.txt")) > 100, "the real rows were read");
    }
    internal static int CtCopy(byte[] b, emon.Port.Cells c) {
        int n = emon.Port.BlobLen(b);
        int i = 0;
        emon.Port.CellsDrop(c, 0);
        while (i < n) {
            emon.Port.CellsPush(c, emon.Port.BlobU8(b, i));
            i += 1;
        }
        return n;
    }
    internal static int CtFuzzFile(int emonT, byte[] bytes, int iters, int cutStep) {
        // Flip 1-6 random bytes `iters` times, and cut the file at every `cut-step` bytes; run each.
        // Nothing is asserted but that no run faults, on any target, whatever it says.
        emon.Port.Cells ar = emon.Port.NewCells();
        emon.Port.Cells dc = emon.Port.NewCells();
        emon.Port.Cells a = emon.Port.NewCells();
        emon.Port.Cells b = emon.Port.NewCells();
        emon.Port.Cells st = emon.Port.NewCells();
        emon.Port.Cells cx = emon.Port.NewCells();
        emon.Port.Cells ox = emon.Port.NewCells();
        emon.Port.Cells cs = emon.Port.NewCells();
        emon.Port.Cells @out = emon.Port.NewCells();
        emon.Port.Cells f0 = emon.Port.NewCells();
        emon.Port.Cells f1 = emon.Port.NewCells();
        emon.Port.Cells f2 = emon.Port.NewCells();
        emon.Port.Cells f3 = emon.Port.NewCells();
        emon.Port.Cells gl = emon.Port.NewCells();
        emon.Port.Cells et = emon.Port.NewCells();
        emon.Port.Cells sp = emon.Port.NewCells();
        emon.Port.Cells pg = emon.Port.NewCells();
        emon.Port.Cells wd = emon.Port.NewCells();
        emon.Port.Cells ln = emon.Port.NewCells();
        emon.Port.Cells work = emon.Port.NewCells();
        emon.Port.Cells rng = emon.Port.NewCells();
        int n = emon.Port.BlobLen(bytes);
        int it = 0;
        int k = 0;
        int flips = 0;
        int cut = 0;
        int runs = 0;
        int at = 0;
        Splitmix.SmSeed(rng, 4242);
        while (it < iters) {
            CtCopy(bytes, work);
            flips = 1 + Splitmix.SmBelow(rng, 6);
            k = 0;
            while (k < flips) {
                at = Splitmix.SmBelow(rng, n);
                emon.Port.CellsSet(work, at, Splitmix.SmBelow(rng, 256));
                k += 1;
            }
            CtRun(emon.Port.SrcOfCells(work), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, pg, wd, ln);
            runs += 1;
            it += 1;
        }
        cut = cutStep;
        while (cut < n) {
            CtCopy(bytes, work);
            emon.Port.CellsDrop(work, cut);
            CtRun(emon.Port.SrcOfCells(work), ar, dc, a, b, st, cx, ox, cs, @out, f0, f1, f2, f3, gl, et, sp, pg, wd, ln);
            runs += 1;
            cut += cutStep;
        }
        return runs;
    }
    [Xunit.Fact]
    public static void TestCorruptedAndCutFilesNeverFault() {
        emon.Testport.AssertThat(CtFuzzFile(0, emon.Testport.TestFile("content/ops.pdf"), 300, 29) > 300, "ops.pdf");
        emon.Testport.AssertThat(CtFuzzFile(0, emon.Testport.TestFile("content/marked.pdf"), 300, 31) > 300, "marked.pdf");
        emon.Testport.AssertThat(CtFuzzFile(0, emon.Testport.TestFile("content/forms.pdf"), 300, 29) > 300, "forms.pdf");
        emon.Testport.AssertThat(CtFuzzFile(0, emon.Testport.TestFile("content/fonts.pdf"), 300, 37) > 300, "fonts.pdf");
        emon.Testport.AssertThat(CtFuzzFile(0, emon.Testport.TestFile("content/damaged.pdf"), 300, 29) > 300, "damaged.pdf");
        emon.Testport.AssertThat(CtFuzzFile(0, emon.Testport.TestFile("pdf/html-chrome.pdf"), 100, 401) > 100, "a Chrome file");
    }
